-- Reviewed 2026 Term 3/4 calendar coverage for weekly research. Each row is
-- derived from the canonical Grade 3 ATP exports; Gemini does not invent dates or outcomes.

begin;

on conflict (academic_year, term, week) do update set
  starts_on = excluded.starts_on,
  ends_on = excluded.ends_on,
  theme = excluded.theme,
  caps_atp_outcomes = excluded.caps_atp_outcomes,
  updated_at = now();

commit;
